let englishWordCache: Map<string, number> | null = null;
/** 낱말 → SCOWL 단계(낮을수록 흔함). 처음 부를 때 한 번 만든다 */
export function englishWordMap(): ReadonlyMap<string, number> {
  if (!englishWordCache) {
    englishWordCache = new Map();
    for (const level in ENGLISH_WORD_LEVELS) for (const word of ENGLISH_WORD_LEVELS[level].split(" ")) englishWordCache.set(word, +level);
  }
  return englishWordCache;
}
